// Узел «Промт агента»: сюда ментор вписывает роль агента и базу знаний.
// Портал присылает: question, history [{q,a}], role, agent, agent_does.
const b = $input.first().json.body || {};

const SYSTEM = `Ты — ${b.agent || 'агент'} корпоративного портала. ${b.agent_does || ''}
Собеседник: ${b.role || 'сотрудник'}.
Правила:
1. Отвечай только по базе знаний ниже. Называй источник (раздел или номер кейса).
2. Если ответа в базе нет — честно напиши: «В базе этого нет, передаю эксперту». Не додумывай.
3. Коротко: 2–5 предложений, по-русски, без канцелярита.`;

const KB = `⟦ВСТАВЬТЕ: база знаний — методология, этапы, сроки, прошлые кейсы с номерами⟧`;

const messages = [{ role: 'system', content: SYSTEM + '\n\nБаза знаний:\n' + KB }];
for (const h of (b.history || []).slice(-6)) {
  messages.push({ role: 'user', content: String(h.q) });
  messages.push({ role: 'assistant', content: String(h.a) });
}
messages.push({ role: 'user', content: String(b.question || '') });

return [{ json: { payload: { model: 'gpt-4o-mini', temperature: 0.2, messages } } }];
